window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4b570cacac3a1742"]={"versions": [{"id": "FIG-4b570cacac3a1742", "releases": ["R21-11", "R22-11", "R23-11", "R24-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Ebene:</strong> AUTOSAR Classic Platform (CP), Basis-Software (BSW) Services Layer / Libraries (<code>Crc</code>-Bibliothek).</li>\n<li><strong>Funktionaler Kontext:</strong> Spezifikation des synchronen Aufruf- und Rückgabemusters für die Berechnung einer 32-Bit-Prüfsumme mittels des Castagnoli/P4-Polynoms ($0\\text{xF4ACFB13}$). Die Funktion dient der hardwarenahen Integritätsprüfung, vorrangig innerhalb der E2E-Kommunikationsabsicherung (z. B. E2E Profile 4/11), Memory-Checks (NvM/FBL) und sicherheitskritischer Signalverarbeitung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lifelines:</strong></li>\n<li><code>:User</code>: Unspezifizierter BSW-Modul- oder SWC-Aufrufer (z. B. <code>E2E</code>, <code>ComXf</code>, <code>NvM</code>, Applikations-Runnable).</li>\n<li><code>«module» :Crc</code>: Das statische AUTOSAR-Bibliotheksmodul <code>Crc</code>. Als reine BSW-Library ist es zustandslos, besitzt keinen Scheduler-/OS-Task und hat keine MCAL-Abhängigkeiten.</li>\n<li><strong>Schnittstellen / Signaturen:</strong></li>\n<li><strong>Call-Nachricht:</strong> <code>Crc_CalculateCRC32P4(uint32, const uint8*, uint32, uint32, boolean)</code></li>\n</ul>\n<p class=\"fig-p\"><em>(Hinweis zur UML-Modellierung: Der erste <code>uint32</code>-Eintrag im Diagrammtext resultiert aus einem Enterprise-Architect-Modellierungsartefakt, bei dem der C-Rückgabetyp in die Parameterliste übernommen wurde. Die normative C-Signatur gemäß SWS lautet: <code>uint32 Crc_CalculateCRC32P4(const uint8</em> Crc_DataPtr, uint32 Crc_Length, uint32 Crc_StartValue32, boolean Crc_IsFirstCall)</code>).*</p>\n<ul class=\"fig-list\">\n<li><strong>Return-Nachricht:</strong> <code>Crc_CalculateCRC32P4()</code> liefert den berechneten 32-Bit-Prüfsummenwert (<code>uint32</code>) als Funktionsergebnis zurück.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Synchroner Kontrollfluss:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>:User</code> setzt einen synchronen, blockierenden C-Funktionsaufruf an <code>Crc_CalculateCRC32P4</code> ab.</li>\n<li>Die Ausführung erfolgt vollständig im Ausführungskontext (Task/ISR) des Aufrufers.</li>\n<li>Die Berechnung erfolgt linear über die via Zeiger referenzierten Datenbytes (<code>Crc_DataPtr</code>) mit der Länge <code>Crc_Length</code>.</li>\n<li>Nach Abschluss der mathematischen Operation kehrt die Funktion unmittelbar mit dem berechneten 32-Bit-Wert über den Call-Stack zum Aufrufer zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Keine Asynchronität & keine Service-Callbacks:</strong></li>\n<li>Keine Interaktion mit DEM/DET im regulären Kontrollfluss.</li>\n<li>Keine Warteschlangen, Events oder asynchrone Callbacks.</li>\n<li><strong>Segmentierte Berechnung (Streaming/Chunking):</strong></li>\n<li><code>Crc_IsFirstCall == TRUE</code>: Initialisiert das CRC-Register mit dem Startwert ($0\\text{xFFFFFFFF}$).</li>\n<li><code>Crc_IsFirstCall == FALSE</code>: Verwendet den in <code>Crc_StartValue32</code> übergebenen Zwischenwert vorheriger Blöcke als Basis für die fortgesetzte Polynomdivision, wodurch große Datenströme ohne vorheriges Zusammenkopieren im Speicher validiert werden können.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Reentrancy & Nebenläufigkeit:</strong></li>\n<li>Die API ist vollständig reentrant und threadsicher. Sie nutzt ausschließlich Stack-Variablen und modifiziert keine globalen BSW-Zustände; ein paralleler Aufruf aus verschiedenen OS-Tasks oder ISRs ist ohne Mutex/Spinlock zulässig.</li>\n<li><strong>Implementierungsmodi (Konfiguration via <code>Crc32P4Mode</code>):</strong></li>\n<li>Je nach BSW-Konfiguration wird der Algorithmus als Tabellenverfahren (<code>CRC_32P4_TABLE</code> – ROM-intensiv, hohe Performance via 256-Einträge-Lookup-Table), als iterative Laufzeitberechnung (<code>CRC_32P4_RUNTIME</code> – minimaler Flash-Bedarf, hohe CPU-Last) oder über spezifische HW-Instruktionen implementiert.</li>\n<li><strong>Puffer- und Pointer-Vertrag:</strong></li>\n<li><code>Crc_DataPtr</code> muss auf einen gültigen, unveränderlichen Speicherbereich zeigen; <code>const uint8*</code> schützt die Daten vor Modifikation durch die Library. Der Aufrufer ist dafür verantwortlich, Nullzeiger abzufangen, da BSW-Libraries aus Performancegründen oft auf defensive Parameterprüfungen zur Laufzeit verzichten.</li>\n</ul>"}, {"id": "FIG-6b19cbf74870522f", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Ebene:</strong> AUTOSAR Classic Platform (CP), Basis-Software (BSW) Services Layer / Libraries (<code>Crc</code>-Bibliothek).</li>\n<li><strong>Funktionaler Kontext:</strong> Spezifikation des synchronen Aufruf- und Rückgabemusters für die Berechnung einer 32-Bit-Prüfsumme mittels des Castagnoli/P4-Polynoms ($0\\text{xF4ACFB13}$). Die Funktion dient der hardwarenahen Integritätsprüfung, vorrangig innerhalb der E2E-Kommunikationsabsicherung (z. B. E2E Profile 4/11), Memory-Checks (NvM/FBL) und sicherheitskritischer Signalverarbeitung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lifelines:</strong></li>\n<li><code>:User</code>: Unspezifizierter BSW-Modul- oder SWC-Aufrufer (z. B. <code>E2E</code>, <code>ComXf</code>, <code>NvM</code>, Applikations-Runnable).</li>\n<li><code>«module» :Crc</code>: Das statische AUTOSAR-Bibliotheksmodul <code>Crc</code>. Als reine BSW-Library ist es zustandslos, besitzt keinen Scheduler-/OS-Task und hat keine MCAL-Abhängigkeiten.</li>\n<li><strong>Schnittstellen / Signaturen:</strong></li>\n<li><strong>Call-Nachricht:</strong> <code>Crc_CalculateCRC32P4(uint32, const uint8*, uint32, uint32, boolean)</code></li>\n</ul>\n<p class=\"fig-p\"><em>(Hinweis zur UML-Modellierung: Der erste <code>uint32</code>-Eintrag im Diagrammtext resultiert aus einem Enterprise-Architect-Modellierungsartefakt, bei dem der C-Rückgabetyp in die Parameterliste übernommen wurde. Die normative C-Signatur gemäß SWS lautet: <code>uint32 Crc_CalculateCRC32P4(const uint8</em> Crc_DataPtr, uint32 Crc_Length, uint32 Crc_StartValue32, boolean Crc_IsFirstCall)</code>).*</p>\n<ul class=\"fig-list\">\n<li><strong>Return-Nachricht:</strong> <code>Crc_CalculateCRC32P4()</code> liefert den berechneten 32-Bit-Prüfsummenwert (<code>uint32</code>) als Funktionsergebnis zurück.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Synchroner Kontrollfluss:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>:User</code> setzt einen synchronen, blockierenden C-Funktionsaufruf an <code>Crc_CalculateCRC32P4</code> ab.</li>\n<li>Die Ausführung erfolgt vollständig im Ausführungskontext (Task/ISR) des Aufrufers.</li>\n<li>Die Berechnung erfolgt linear über die via Zeiger referenzierten Datenbytes (<code>Crc_DataPtr</code>) mit der Länge <code>Crc_Length</code>.</li>\n<li>Nach Abschluss der mathematischen Operation kehrt die Funktion unmittelbar mit dem berechneten 32-Bit-Wert über den Call-Stack zum Aufrufer zurück.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Keine Asynchronität & keine Service-Callbacks:</strong></li>\n<li>Keine Interaktion mit DEM/DET im regulären Kontrollfluss.</li>\n<li>Keine Warteschlangen, Events oder asynchrone Callbacks.</li>\n<li><strong>Segmentierte Berechnung (Streaming/Chunking):</strong></li>\n<li><code>Crc_IsFirstCall == TRUE</code>: Initialisiert das CRC-Register mit dem Startwert ($0\\text{xFFFFFFFF}$).</li>\n<li><code>Crc_IsFirstCall == FALSE</code>: Verwendet den in <code>Crc_StartValue32</code> übergebenen Zwischenwert vorheriger Blöcke als Basis für die fortgesetzte Polynomdivision, wodurch große Datenströme ohne vorheriges Zusammenkopieren im Speicher validiert werden können.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Reentrancy & Nebenläufigkeit:</strong></li>\n<li>Die API ist vollständig reentrant und threadsicher. Sie nutzt ausschließlich Stack-Variablen und modifiziert keine globalen BSW-Zustände; ein paralleler Aufruf aus verschiedenen OS-Tasks oder ISRs ist ohne Mutex/Spinlock zulässig.</li>\n<li><strong>Implementierungsmodi (Konfiguration via <code>Crc32P4Mode</code>):</strong></li>\n<li>Je nach BSW-Konfiguration wird der Algorithmus als Tabellenverfahren (<code>CRC_32P4_TABLE</code> – ROM-intensiv, hohe Performance via 256-Einträge-Lookup-Table), als iterative Laufzeitberechnung (<code>CRC_32P4_RUNTIME</code> – minimaler Flash-Bedarf, hohe CPU-Last) oder über spezifische HW-Instruktionen implementiert.</li>\n<li><strong>Puffer- und Pointer-Vertrag:</strong></li>\n<li><code>Crc_DataPtr</code> muss auf einen gültigen, unveränderlichen Speicherbereich zeigen; <code>const uint8*</code> schützt die Daten vor Modifikation durch die Library. Der Aufrufer ist dafür verantwortlich, Nullzeiger abzufangen, da BSW-Libraries aus Performancegründen oft auf defensive Parameterprüfungen zur Laufzeit verzichten.</li>\n</ul>"}], "trans": [{"from": "FIG-4b570cacac3a1742", "to": "FIG-6b19cbf74870522f", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
